import { escapeHtml } from '../../../engine/utils/escape-html';
import { DOCUMENT_CSS, documentHeaderHtml, shiftDetailsHtmlFromView, staffCellHtmlFromView } from './adolphus-document';
import { buildPreShiftReportViewModel, PreShiftReportData, PreShiftReportViewModel } from './pre-shift-report.view-model';

export type { PreShiftReportData, PreShiftReportStaffRow } from './pre-shift-report.view-model';

/**
 * Pre-shift SHIFT ATTENDANCE SHEET (Adolphus Group template, owner design 2026-10-17), Chromium HTML. Generated by the
 * worker (`shift-report-scheduler.job.ts`) REPORT_AVAILABLE_BEFORE_MINUTES before the shift. The QR is the real signed
 * Shift QR from `AttendanceQrService` + `QrImageService`, embedded as a base64 PNG — never a placeholder; it carries no
 * account token. Ratings, confirmation and signatures are not part of this before-shift document.
 *
 * Every printed string comes from the shared view-model (`pre-shift-report.view-model.ts`), which the native PDF
 * renderer also consumes; this file only lays those strings out as HTML, escaping every one of them.
 */
export function renderPreShiftReportHtml(data: PreShiftReportData): string {
  return preShiftReportHtmlFromViewModel(buildPreShiftReportViewModel(data));
}

const COLUMN_STYLE: Record<number, string> = { 0: ' style="width:44%"' };

export function preShiftReportHtmlFromViewModel(vm: PreShiftReportViewModel): string {
  const rows = vm.rows
    .map(
      (r) => `
      <tr>
        <td>${staffCellHtmlFromView(r.initials, r.name, r.sub)}</td>
        <td>${escapeHtml(r.start)}</td>
        <td>${escapeHtml(r.finish)}</td>
        <td>${escapeHtml(r.breakText)}</td>
      </tr>`,
    )
    .join('');
  const head = vm.columns.map((c, i) => `<th${COLUMN_STYLE[i] ?? ''}>${escapeHtml(c)}</th>`).join('');
  const notes = vm.notes.muted ? `<span class="muted">${escapeHtml(vm.notes.text)}</span>` : escapeHtml(vm.notes.text);

  return `<!doctype html>
<html>
<head>
<meta charset="utf-8">
<title>${escapeHtml(vm.documentTitle)}</title>
<style>
${DOCUMENT_CSS}
  .qr { width: 150px; border: 1px solid #E3E5E2; border-radius: 10px; background: #F6F7F5; padding: 10px; text-align: center; flex: none; }
  .qr img { width: 128px; height: 128px; display: block; margin: 0 auto 6px; }
  .qr b { display: block; font-size: 10px; letter-spacing: .3px; }
  .qr small { color: #8A8F8C; font-size: 8.5px; }
</style>
</head>
<body>
  ${documentHeaderHtml(vm.title)}
  <section class="top">
    <div>${shiftDetailsHtmlFromView(vm.details)}</div>
    <div class="qr">
      <img src="data:image/png;base64,${vm.qr.pngBase64}" alt="${escapeHtml(vm.qr.alt)}">
      <b>${escapeHtml(vm.qr.label)}</b>
      <small>${escapeHtml(vm.qr.caption)}</small>
    </div>
  </section>
  <div class="summary">${escapeHtml(vm.summary)}</div>
  <table>
    <thead><tr>${head}</tr></thead>
    <tbody>${rows || `<tr><td colspan="${vm.columns.length}" class="muted">${escapeHtml(vm.emptyText)}</td></tr>`}</tbody>
  </table>
  <div class="note-line">${escapeHtml(vm.noteLine)}</div>
  <section class="bottom">
    <div>
      <h3>${escapeHtml(vm.notesHeading)}</h3>
      <p class="notes-text">${notes}</p>
      <p class="muted">${escapeHtml(vm.qrScopeNote)}</p>
    </div>
    <div>
      <h3>${escapeHtml(vm.beforeShiftHeading)}</h3>
${vm.beforeShiftLines.map((l) => `      <p>${escapeHtml(l)}</p>`).join('\n')}
    </div>
  </section>
</body>
</html>`;
}
